WITH src AS (SELECT *, CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END AS is_purchase FROM web_events WHERE duration_sec IS NOT NULL AND event_type = 'search' AND page IN ('/checkout', '/cart')), event_type_summary AS (SELECT event_type, page, AVG(duration_sec) AS avg_duration_sec, AVG(is_purchase) AS avg_is_purchase FROM src GROUP BY event_type, page) SELECT * FROM event_type_summary WHERE avg_duration_sec >= 350 ORDER BY page, event_type LIMIT 3;
